import sys
import json
import re
from typing import Dict, Any

def load_allowed_tokens() -> set:
    with open("allowed_tokens.txt", "r") as f:
        return {line.strip() for line in f if line.strip()}

def validate_token(token: str, allowed_tokens: set) -> bool:
    return token in allowed_tokens

def parse_json(json_path: str) -> Dict[str, Any]:
    with open(json_path, "r") as f:
        return json.load(f)

def evaluate_expression(expr: str, variables: Dict[str, Any]) -> str:
    try:
        # Replace variables with their values
        for var, value in variables.items():
            expr = expr.replace(var, str(value))
        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except:
        return "UNDEFINED"

def render_template(template_path: str, variables: Dict[str, Any]) -> str:
    with open(template_path, "r") as f:
        template = f.read()
    # Replace all {{expression}} placeholders
    pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
    def replacer(match):
        expr = match.group(1)
        return evaluate_expression(expr, variables)
    return pattern.sub(replacer, template)

def main():
    if len(sys.argv) != 4:
        sys.exit(2)

    json_path = sys.argv[1]
    template_path = sys.argv[2]
    token = sys.argv[3]

    allowed_tokens = load_allowed_tokens()
    if not validate_token(token, allowed_tokens):
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    try:
        variables = parse_json(json_path)
        output = render_template(template_path, variables)
        print(output)
        sys.exit(0)
    except Exception:
        print("UNDEFINED", file=sys.stderr)
        sys.exit(2)

if __name__ == "__main__":
    main()

import sys
import json
import re

def validate_token(json_data, provided_token):
    if json_data.get('ticket_token') != provided_token:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

def evaluate_expression(expression, variables):
    try:
        # Replace variables with their values and evaluate the expression
        for var, value in variables.items():
            expression = expression.replace(var, str(value))
        # Use eval with a restricted namespace to prevent arbitrary code execution
        return str(eval(expression, {'__builtins__': None}, {}))
    except Exception:
        return "0"  # Fallback to 0 if evaluation fails

def render_template(template_path, variables):
    with open(template_path, 'r') as f:
        template = f.read()

    # Replace all {{expression}} with evaluated expressions
    for var, value in variables.items():
        template = template.replace(f"{{{{{var}}}}}", str(value))

    # Handle arithmetic expressions in placeholders
    pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
    def replace_match(match):
        expr = match.group(1)
        return evaluate_expression(expr, variables)

    rendered = pattern.sub(replace_match, template)
    return rendered

def main():
    if len(sys.argv) != 4:
        print("Usage: python render_ticket.py <json_file> <template_file> <ticket_token>", file=sys.stderr)
        sys.exit(1)

    json_file = sys.argv[1]
    template_file = sys.argv[2]
    provided_token = sys.argv[3]

    with open(json_file, 'r') as f:
        data = json.load(f)

    validate_token(data, provided_token)
    variables = {k: v for k, v in data.items() if k != 'ticket_token'}
    output = render_template(template_file, variables)
    print(output)

if __name__ == "__main__":
    main()

import sys
import json
import re
from operator import add, sub, mul

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values and evaluate the expression
        for var, val in variables.items():
            expr = expr.replace(var, str(val))
        # Use eval with a restricted namespace to prevent arbitrary code execution
        return eval(expr, {'__builtins__': None}, {'+': add, '-': sub, '*': mul})
    except Exception:
        return ""

def render_ticket():
    if len(sys.argv) != 4:
        print("Usage: python render_ticket.py <json_file> <template_file> <ticket_token>", file=sys.stderr)
        sys.exit(1)

