    ticket_token = sys.argv[3]

    try:
        with open(json_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading JSON file: {e}", file=sys.stderr)
        sys.exit(2)

    if 'ticket_token' not in data or data['ticket_token'] != ticket_token:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    variables = {k: v for k, v in data.items() if k != 'ticket_token'}

    try:
        with open(template_path, 'r') as f:
            template = f.read()
    except Exception as e:
        print(f"Error reading template file: {e}", file=sys.stderr)
        sys.exit(2)

    # Replace all {{expression}} with evaluated expressions
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr, variables))

    rendered = re.sub(r'\{\{\s*([^}]+)\s*\}\}', replace_match, template)
