import sys
import json
import re

def main():
    if len(sys.argv) != 4:
        sys.exit(2)

    json_path = sys.argv[1]
    template_path = sys.argv[2]
    ticket_token = sys.argv[3]

    with open(json_path, 'r') as f:
        data = json.load(f)

    if data.get('ticket_token') != ticket_token:
        print('ACCESS DENIED', file=sys.stderr)
        sys.exit(2)

    with open(template_path, 'r') as f:
        template = f.read()

    variables = data.keys()
    variables.remove('ticket_token')

    def evaluate_expr(expr):
        tokens = re.findall(r'(\d+|[a-zA-Z_]+|\+|\*)', expr)
        stack = []
        output = []
        operators = []

        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in variables:
                stack.append(data[token])
            elif token == '*':
                operators.append(token)
            elif token == '+':
                while operators and operators[-1] == '*':
                    output.append(operators.pop())
                operators.append(token)

        while operators:
            output.append(operators.pop())

        for op in output:
            if op == '*':
                a = stack.pop()
                b = stack.pop()
                stack.append(a * b)
            elif op == '+':
                a = stack.pop()
                b = stack.pop()
                stack.append(a + b)

        return str(stack[0])

    pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
    result = template
    for match in pattern.finditer(template):
        expr = match.group(1)
        result = result.replace(match.group(0), evaluate_expr(expr))

    print(result)

if __name__ == '__main__':
    main()
